import { REQ_IMAGE_VARIANTS } from '@/data/reqImageVariants';

/**
 * Responsive image renderer for the requirement portal photos.
 *
 * Every rendered photo has a WebP + JPEG ladder generated by
 * scripts/optimize_images.py and described by src/data/reqImageVariants.ts.
 * We emit a <picture> so browsers that support WebP pick the smaller WebP
 * file, while the <img> keeps a JPEG srcset as the universal fallback.
 *
 * Intrinsic width/height are always set on the <img> so the browser can
 * reserve the correct box before the bytes arrive (no layout shift / CLS).
 *
 * If a path is not in the manifest (e.g. an image that was never processed)
 * we fall back to the plain <img> exactly as before, so nothing breaks and we
 * never advertise a srcset URL for a file that does not exist on disk.
 */

/**
 * Main question photo.
 *
 * The photo lives in a `max-w-4xl` (896px) container with `px-4`, inside a
 * question card padded `p-5 sm:p-6` and indented `sm:pl-9`, inside a 1px
 * bordered wrapper. Measured rendered CSS width: 776px at a 1280px viewport,
 * 314px at a 390px viewport. The two calc() branches reproduce that.
 */
export const PHOTO_SIZES =
  '(max-width: 639px) calc(100vw - 76px), (max-width: 896px) calc(100vw - 120px), 776px';

/**
 * imagechoice option thumbnail: one per column of a `sm:grid-cols-2` grid
 * inside the same card, so roughly half the photo width (12px grid gap).
 */
export const THUMB_SIZES =
  '(max-width: 639px) calc(100vw - 76px), (max-width: 896px) calc((100vw - 132px) / 2), 382px';

interface ResponsiveImageProps {
  src: string;
  alt: string;
  sizes: string;
  className?: string;
}

function stripExtension(path: string): string {
  const slash = path.lastIndexOf('/');
  const dot = path.lastIndexOf('.');
  return dot > slash ? path.slice(0, dot) : path;
}

export default function ResponsiveImage({
  src,
  alt,
  sizes,
  className,
}: ResponsiveImageProps) {
  const variant = REQ_IMAGE_VARIANTS[src];

  // Unknown / unprocessed image: keep the previous behaviour verbatim.
  if (!variant) {
    return (
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        className={className}
      />
    );
  }

  const base = stripExtension(src);

  // A WebP file exists for every candidate width.
  const webpSrcset = variant.widths
    .map((w) => `${base}-${w}.webp ${w}w`)
    .join(', ');

  // A downscaled JPEG exists for every width below native; the native-width
  // JPEG is the original file, which keeps existing URLs working.
  const jpegCandidates = variant.widths
    .filter((w) => w < variant.width)
    .map((w) => `${base}-${w}.jpg ${w}w`);
  jpegCandidates.push(`${src} ${variant.width}w`);

  return (
    <picture className="block">
      <source type="image/webp" srcSet={webpSrcset} sizes={sizes} />
      <img
        src={src}
        srcSet={jpegCandidates.join(', ')}
        sizes={sizes}
        width={variant.width}
        height={variant.height}
        alt={alt}
        loading="lazy"
        decoding="async"
        className={className}
      />
    </picture>
  );
}
